import { LinkTarget } from "../ks-link/types";
import { DropdownItem } from "../ks-dropdown-menu-list/types";
export type BreadcrumbSize = 'md' | 'lg';
export interface BreadcrumbItem {
    label: string;
    active?: boolean;
    disabled?: boolean;
    target?: LinkTarget;
    href?: string;
    onClick?: () => void;
}
export interface BreadcrumbDropdownItem {
    label: string;
    active?: boolean;
    disabled?: boolean;
    /** Trigger method for the dropdown */
    trigger?: 'click' | 'hover' | 'focus';
    children: (DropdownItem & {
        active?: boolean;
        href?: string;
    })[];
}
